/**
 * What built JavaScript is made of: every generated byte attributed to the
 * source module and package it came from, through the build's source maps.
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { gzipSync } from "node:zlib";

import { regionPackage } from "./build-output.mjs";

const BASE64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const DIGIT = new Int8Array(128).fill(-1);
for (let i = 0; i < BASE64.length; i++) DIGIT[BASE64.charCodeAt(i)] = i;

const UNMAPPED = "(unmapped)";
const JS_FILE = /\.m?js$/;
const NODE_MODULES = /^(?:.*\/)?node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?/;
const VIRTUAL_PREFIX = String.fromCharCode(0);
const VIRTUAL = /virtual:|^\/?@id\//;
const LEADING_PARENTS = /^(?:\.\.\/)+/;
const TOP_MODULES = 40;
const WHITESPACE = /^\s*$/;

/**
 * Decode a source map's `mappings` into, per generated line, segments of
 * `[generatedColumn, sourceIndex, sourceLine, sourceColumn]`, all absolute.
 * Segments without a source have only the column.
 */
export function decodeMappings(mappings) {
	const lines = [];
	let source = 0;
	let sourceLine = 0;
	let sourceColumn = 0;
	let name = 0;
	for (const lineText of mappings.split(";")) {
		const segments = [];
		let column = 0;
		if (lineText.length > 0) {
			for (const segmentText of lineText.split(",")) {
				if (segmentText.length === 0) continue;
				const values = [];
				let value = 0;
				let shift = 0;
				for (let i = 0; i < segmentText.length; i++) {
					const digit = DIGIT[segmentText.charCodeAt(i)];
					if (digit === undefined || digit < 0)
						throw new Error(`Bad mapping character in "${segmentText}"`);
					value += (digit & 31) << shift;
					if (digit & 32) {
						shift += 5;
						continue;
					}
					values.push(value & 1 ? -(value >>> 1) : value >>> 1);
					value = 0;
					shift = 0;
				}
				column += values[0];
				if (values.length >= 4) {
					source += values[1];
					sourceLine += values[2];
					sourceColumn += values[3];
					if (values.length >= 5) name += values[4];
					segments.push([column, source, sourceLine, sourceColumn]);
				} else {
					segments.push([column]);
				}
			}
		}
		lines.push(segments);
	}
	return lines;
}

/**
 * Generated bytes and text per source for one file. `resolveSource` turns a
 * segment into the source it is credited to (by default the map's source).
 * Indentation goes to the code on its line. Other text no segment starts,
 * such as lines between segments, goes to the source before it, so code
 * before the first mapped segment, such as a chunk's imports, is unmapped.
 */
export function attributeFile(code, map, { resolveSource } = {}) {
	const totals = new Map();
	const add = (source, text) => {
		if (text.length === 0) return;
		const entry = totals.get(source) ?? { bytes: 0, parts: [] };
		entry.bytes += Buffer.byteLength(text);
		entry.parts.push(text);
		totals.set(source, entry);
	};
	const sourceOf = (segment) => {
		if (segment.length < 2) return UNMAPPED;
		return resolveSource ? resolveSource(segment) : (map.sources[segment[1]] ?? UNMAPPED);
	};
	const lines = code.split("\n");
	const decoded = decodeMappings(map.mappings ?? "");
	let current = UNMAPPED;
	lines.forEach((line, index) => {
		const segments = (decoded[index] ?? []).toSorted((a, b) => a[0] - b[0]);
		const lead = line.slice(0, segments[0]?.[0] ?? line.length);
		const first = segments[0] ? sourceOf(segments[0]) : UNMAPPED;
		add(first !== UNMAPPED && WHITESPACE.test(lead) ? first : current, lead);
		segments.forEach((segment, i) => {
			const end = segments[i + 1]?.[0] ?? line.length;
			const source = sourceOf(segment);
			if (source !== UNMAPPED) current = source;
			add(source, line.slice(segment[0], end));
		});
		if (index < lines.length - 1) add(current, "\n");
	});
	return totals;
}

/** Index of the last segment at or before `column` in a line, whose segments are in column order. */
function segmentAt(segments, column) {
	let lo = 0;
	let hi = segments.length - 1;
	let found = -1;
	while (lo <= hi) {
		const mid = (lo + hi) >> 1;
		if (segments[mid][0] <= column) {
			found = mid;
			lo = mid + 1;
		} else {
			hi = mid - 1;
		}
	}
	return found;
}

/**
 * A resolver for `attributeFile` that follows one more level of source
 * maps: when a source is a workspace package's built file with its own map,
 * the segment is credited to that package's original module.
 */
export function nestedResolver(map, mapDir, { workspace } = {}) {
	const cache = new Map();
	const packagesDir = workspace ? join(workspace, "packages") : null;
	const nested = (absolute) => {
		if (cache.has(absolute)) return cache.get(absolute);
		let entry = null;
		const mapFile = `${absolute}.map`;
		if (
			packagesDir &&
			absolute.startsWith(`${packagesDir}${sep}`) &&
			!absolute.includes(`${sep}node_modules${sep}`) &&
			existsSync(mapFile)
		) {
			try {
				const inner = JSON.parse(readFileSync(mapFile, "utf8"));
				entry = {
					lines: decodeMappings(inner.mappings ?? ""),
					sources: inner.sources ?? [],
					dir: inner.sourceRoot ? resolve(dirname(mapFile), inner.sourceRoot) : dirname(mapFile),
				};
			} catch {
				entry = null;
			}
		}
		cache.set(absolute, entry);
		return entry;
	};
	return (segment) => {
		const source = map.sources[segment[1]];
		if (source === undefined) return UNMAPPED;
		if (!mapDir || isVirtual(source)) return source;
		const absolute = resolve(mapDir, source);
		const inner = nested(absolute);
		if (!inner) return absolute;
		const line = inner.lines[segment[2]];
		if (!line) return absolute;
		const at = segmentAt(line, segment[3]);
		const hit = at >= 0 ? line[at] : null;
		if (!hit || hit.length < 2 || inner.sources[hit[1]] === undefined) return absolute;
		return resolve(inner.dir, inner.sources[hit[1]]);
	};
}

const isVirtual = (source) => source.startsWith(VIRTUAL_PREFIX) || VIRTUAL.test(source);

/**
 * A module name and package for a source path from a map, relative to the
 * map's directory. Paths are made relative to the site (its own code) or to
 * the workspace (packages and node_modules).
 */
export function classifySource(source, { mapDir, siteDir, workspace }) {
	if (source === UNMAPPED) return { module: UNMAPPED, package: UNMAPPED };
	if (isVirtual(source)) {
		return { module: source.replace(VIRTUAL_PREFIX, ""), package: "(virtual modules)" };
	}
	const absolute = mapDir ? resolve(mapDir, source) : source;
	const inside = (root) => root && (absolute === root || absolute.startsWith(`${root}${sep}`));
	let path = source.replace(LEADING_PARENTS, "");
	if (inside(siteDir)) path = relative(siteDir, absolute);
	else if (inside(workspace)) path = relative(workspace, absolute);
	path = path.split(sep).join("/");
	if (inside(siteDir) && !path.includes("node_modules/"))
		return { module: path, package: "(site)" };
	return { module: path.replace(NODE_MODULES, ""), package: regionPackage(path) };
}

/**
 * Bytes per package and module over a set of built files with their maps.
 * Each package's gzip size is its own text compressed alone, so the sizes
 * add up to more than the bundle's gzip size.
 */
export function composeFiles(files, context = {}) {
	const packages = new Map();
	const modules = new Map();
	let bytes = 0;
	let mappedFiles = 0;
	for (const { code, map, mapDir } of files) {
		bytes += Buffer.byteLength(code);
		if (!map) {
			const entry = packages.get(UNMAPPED) ?? { bytes: 0, parts: [] };
			entry.bytes += Buffer.byteLength(code);
			entry.parts.push(code);
			packages.set(UNMAPPED, entry);
			continue;
		}
		mappedFiles++;
		const resolveSource = nestedResolver(map, mapDir, context);
		for (const [source, part] of attributeFile(code, map, { resolveSource })) {
			const { module, package: pkg } = classifySource(source, { ...context, mapDir });
			const p = packages.get(pkg) ?? { bytes: 0, parts: [] };
			p.bytes += part.bytes;
			for (const text of part.parts) p.parts.push(text);
			packages.set(pkg, p);
			const m = modules.get(module) ?? { module, package: pkg, bytes: 0 };
			m.bytes += part.bytes;
			modules.set(module, m);
		}
	}
	return {
		files: files.length,
		mappedFiles,
		bytes,
		packages: Array.from(packages, ([name, p]) => ({
			package: name,
			bytes: p.bytes,
			gzipBytes: gzipSync(p.parts.join("")).length,
		})).toSorted((a, b) => b.bytes - a.bytes),
		modules: [...modules.values()].toSorted((a, b) => b.bytes - a.bytes).slice(0, TOP_MODULES),
	};
}

function readWithMap(file) {
	const code = readFileSync(file, "utf8");
	const mapFile = `${file}.map`;
	if (!existsSync(mapFile)) return { code, map: null, mapDir: null };
	try {
		const map = JSON.parse(readFileSync(mapFile, "utf8"));
		const root = map.sourceRoot ? resolve(dirname(mapFile), map.sourceRoot) : dirname(mapFile);
		return { code, map, mapDir: root };
	} catch {
		return { code, map: null, mapDir: null };
	}
}

function jsFiles(dir) {
	if (!existsSync(dir)) return [];
	return readdirSync(dir, { withFileTypes: true, recursive: true })
		.filter((e) => e.isFile() && JS_FILE.test(e.name))
		.map((e) => join(e.parentPath, e.name));
}

/** Composition of every JavaScript file in the built server. */
export function serverComposition(site, workspace) {
	const files = jsFiles(join(site.siteDir, "dist/server")).map(readWithMap);
	return composeFiles(files, { siteDir: site.siteDir, workspace });
}

/** Composition of the admin document's initial JavaScript, by the URLs it loaded. */
export function adminComposition(site, urls, workspace) {
	const files = [];
	for (const url of urls) {
		const file = join(site.siteDir, "dist/client", decodeURIComponent(new URL(url).pathname));
		if (existsSync(file)) files.push(readWithMap(file));
	}
	return composeFiles(files, { siteDir: site.siteDir, workspace });
}

const packageBytes = (comp, name) => comp.packages.find((p) => p.package === name)?.bytes ?? 0;

/**
 * Packages whose bytes changed by at least `minBytes` between two
 * compositions, largest change first. A package missing on one side counts
 * as zero there.
 */
export function compositionDeltas(before, after, { minBytes = 2048 } = {}) {
	const names = new Set([...before.packages, ...after.packages].map((p) => p.package));
	return Array.from(names, (name) => {
		const b = packageBytes(before, name);
		const a = packageBytes(after, name);
		return { package: name, before: b, after: a, delta: a - b };
	})
		.filter((d) => Math.abs(d.delta) >= minBytes)
		.toSorted((x, y) => Math.abs(y.delta) - Math.abs(x.delta));
}
